'use strict';

const { ExprError } = require('./errors');

/** Python float %: the result takes the divisor's sign; zero is positive zero. */
function pythonMod(left, right) {
  const mod = left % right;
  if (mod === 0) return 0;
  return (right < 0) !== (mod < 0) ? mod + right : mod;
}

/** CPython float floor division (via fmod, then rounded); zero is positive zero. */
function floorDiv(left, right) {
  const mod = left % right;
  let div = (left - mod) / right;
  if (mod && (right < 0) !== (mod < 0)) div -= 1;
  if (div === 0) return 0;
  const floor = Math.floor(div);
  return div - floor > 0.5 ? floor + 1 : floor;
}

/** Python float pow for the cases where JavaScript returns NaN instead. */
function power(left, right) {
  if (left === 1) return 1;
  if (left === -1 && (right === Infinity || right === -Infinity)) return 1;
  return left ** right;
}

function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '**': return power(left, right);
    case '//': return floorDiv(left, right);
    case '%': return pythonMod(left, right);
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

