const { evaluate, ExprError } = require('./src/index');
const exprs = ['-2**2', '2**-1', '2**3**2', '1//0.1', '1%0.1', '-5//x', '-5%x', '1<2<3', '3>2>1', 'max(1<2,0)', 'min(0,(1>2))', '7.5//-2', '-7.5%2', '(1<2)+1', '1 < 3 > 2', '2 * -3 ** 2', '- - -2'];
for (const e of exprs) console.log(e, '=>', evaluate(e, { x: Infinity }));
const errs = ['1 +  ', '  foo(1)', 'abs(1, 2)', 'min()', '1 / 0', ' 1 $', '1 + (2', 'y + 1', '  2 )'];
for (const e of errs) {
  try { evaluate(e); console.log(e, 'NO ERROR'); } catch (err) { console.log(JSON.stringify(e), err instanceof ExprError, err.column, err.message); }
}
let reads = 0;
const vars = { get a() { reads++; return 2; } };
console.log(evaluate('1 < a < 3', vars), reads, evaluate('5 < a < (1/0)', vars), reads);
const big = Array.from({ length: 200000 }, (_, i) => String(i % 7 + 1)).join(' + ');
let t = Date.now(); console.log(evaluate(big), Date.now() - t, 'ms');
const cmp = Array.from({ length: 200000 }, (_, i) => String(i)).join(' < ');
t = Date.now(); console.log(evaluate(cmp), Date.now() - t, 'ms');
const signs = '-'.repeat(200000) + '1';
t = Date.now(); console.log(evaluate(signs), Date.now() - t, 'ms');
